        sb.append("Diárias: R$ ").append(res.subtotal).append("\n");
        if (res.discount.compareTo(java.math.BigDecimal.ZERO) > 0) {
            sb.append("Desconto: R$ ").append(res.discount).append("\n");
        }
        sb.append("Total: R$ ").append(res.total);
        return sb.toString();
